{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The ruined city looms ahead.",
      "visual_description": "Crumbled stone walls and broken royal banners flap in the wind under a grey sky.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Mara studies her map at the city gate.",
      "visual_description": "Mara kneels on the cobblestones, spreading a worn map while the glass diver peers over her shoulder. The massive iron gate stands ajar, rusted and silent.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning.",
      "visual_description": "Inside a shattered archway, the oracle lamp's flame dances, casting long shadows as its single eye opens wide.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "A clockwork fox sniffs the path ahead.",
      "visual_description": "The tin fox scurries over rubble, its key-wind tail ticking, blue eyes scanning the debris for signs of danger.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector blocks the way.",
      "visual_description": "Curled on a pile of ledgers in the middle of a courtyard, the sleeping tax collector snores softly, stamped papers stuck to his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara tries to wake the tax collector.",
      "visual_description": "Mara shakes the tax collector's shoulder gently, but he only mutters and turns over, clutching his ledger pillow tighter.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver peers into a cursed tower.",
      "visual_description": "A spiral tower leans precariously, its windows reflecting a sickly green light. The glass diver presses his helmet against the grimy glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Townspeople huddle behind boarded windows.",
      "visual_description": "Frightened faces peer through cracks in wooden shutters as armored patrols march past in the street below.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The tin fox reports back to Mara.",
      "visual_description": "The tin fox clicks and whirs, pointing its nose toward a side alley. Mara nods and marks her map with ink-stained fingers.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The oracle lamp warns of a trap.",
      "visual_description": "Its flame sputters and dims, the eye narrowing as the lamp whispers a low, crackling warning about the path ahead.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver swims through a broken window.",
      "visual_description": "He presses his hands against the glass, which ripples like water, and steps through into a dark chamber beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Inside, a magic door hums with symbols.",
      "visual_description": "A tall door inscribed with glowing runes pulses with a soft blue light, blocking the corridor.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Mara deciphers the runes with her compass.",
      "visual_description": "Mara holds her brass compass up to the door, tracing the runes as the needle spins and aligns.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The tax collector sleepwalks into the room.",
      "visual_description": "Still dozing, the sleeping tax collector shuffles in, mumbling about overdue forms, and nudges the door with his shoulder.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The door swings open, revealing a treasure room.",
      "visual_description": "Golden light spills out, illuminating piles of coins and gems, but the glass diver steps past them, looking for the exit.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols block the main route.",
      "visual_description": "Clanking footsteps echo as armored figures round a corner, forcing the group to double back toward the bridge.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge is cracked but crossable.",
      "visual_description": "A stone bridge spans a deep gorge, its surface broken in places, with old royal banners tied to the railings.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They escape across the bridge as it crumbles.",
      "visual_description": "The group dashes across the swaying stones; behind them, the bridge collapses into the chasm, cutting off pursuit.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

